import { getSharedPayloads, useIncomingShare } from 'expo-sharing'
import { useRouter } from 'expo-router'
import { useEffect, useRef, useState } from 'react'
import { Alert } from 'react-native'

import { useAuth, useSupabaseSync } from '@/hooks'
import { extractSharedUrls } from '@/lib/incomingShare'
import { useCollectionsStore, useLinksStore } from '@/stores'

/**
 * Consumes native share-extension payloads and saves their web URL(s).
 *
 * This component is intentionally native-only. The sharing receiver is
 * generated by the expo-sharing config plugin and is not available on web.
 */
export function ShareReceiver() {
  const [nativeReceiverReady] = useState(() => {
    // Expo Go and development builds created before the config-plugin change
    // do not have the iOS app-group entry required by expo-sharing. Probe the
    // native module defensively so that this is a recoverable setup state,
    // rather than an exception that takes down the root ErrorBoundary.
    try {
      getSharedPayloads()
      return true
    } catch (error) {
      console.warn(
        '[ShareReceiver] Incoming sharing is unavailable in this native binary. Rebuild the app after enabling expo-sharing in app.json.',
        error
      )
      return false
    }
  })

  if (!nativeReceiverReady) return null

  return <IncomingShareProcessor />
}

function IncomingShareProcessor() {
  const router = useRouter()
  const { user } = useAuth()
  const {
    sharedPayloads,
    resolvedSharedPayloads,
    isResolving,
    clearSharedPayloads,
    refreshSharePayloads,
  } =
    useIncomingShare()
  const ensureUnsortedCollection = useCollectionsStore((state) => state.ensureUnsortedCollection)
  const links = useLinksStore((state) => state.links)
  const addLink = useLinksStore((state) => state.addLink)
  const { pushLink } = useSupabaseSync()
  const processedPayloadKeyRef = useRef<string | null>(null)

  useEffect(() => {
    // The native module keeps payloads available until they are explicitly
    // cleared. Reset the key once the hook observes that clear operation so a
    // second share of the same URL is still accepted.
    if (sharedPayloads.length === 0) {
      processedPayloadKeyRef.current = null
      return
    }

    if (!user || isResolving) return

    const payloadKey = JSON.stringify(sharedPayloads)
    if (processedPayloadKeyRef.current === payloadKey) return

    // Do not inspect the store before AsyncStorage has restored it. The store
    // subscriptions above cause this effect to run again after hydration.
    if (!useLinksStore.persist.hasHydrated() || !useCollectionsStore.persist.hasHydrated()) return
    processedPayloadKeyRef.current = payloadKey

    const values = [
      ...sharedPayloads,
      ...resolvedSharedPayloads,
    ].map(({ value, shareType }) => ({ value, shareType }))
    const urls = extractSharedUrls(values)

    if (urls.length === 0) {
      clearSharedPayloads()
      refreshSharePayloads()
      Alert.alert(
        'Link not saved',
        'Thannu can save shared web links right now. Images, videos, and files are not supported yet.',
        [{ text: 'OK', onPress: () => router.replace('/(tabs)' as never) }]
      )
      return
    }

    const unsortedCollection = ensureUnsortedCollection()
    const createdLinks = urls.flatMap((url) => {
      const alreadySaved = links.some((link) => link.url === url)
      if (alreadySaved) return []

      const id = addLink({
        url,
        collectionId: unsortedCollection.id,
      })
      const created = useLinksStore.getState().links.find((link) => link.id === id)
      return created ? [created] : []
    })

    clearSharedPayloads()
    refreshSharePayloads()

    // Local persistence succeeds even when the network is unavailable. A
    // later sync can reconcile these records, so a Supabase failure should not
    // make the user repeat the share action and create a duplicate.
    Promise.all(createdLinks.map((link) => pushLink(link).catch((error) => {
      console.warn('[ShareReceiver] Failed to sync shared link:', error)
    }))).then(() => {
      const savedCount = createdLinks.length
      const message = savedCount > 0
        ? `${savedCount} ${savedCount === 1 ? 'link was' : 'links were'} saved to Unsorted.`
        : 'That link is already in your library.'

      Alert.alert('Share received', message, [
        { text: 'OK', onPress: () => router.replace('/(tabs)' as never) },
      ])
    })
  }, [
    addLink,
    clearSharedPayloads,
    ensureUnsortedCollection,
    isResolving,
    links,
    resolvedSharedPayloads,
    refreshSharePayloads,
    router,
    sharedPayloads,
    pushLink,
    user,
  ])

  return null
}
